/* TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX. */
/* Authors: Tom; Brendon (integrator) added PitchDetector_SamplesSinceEstimate for the Autotune's look-ahead (30 Oct 2026, with an AI coding assistant). */
/*
 * Pitch detector: how high is the voice? It measures the fundamental
 * frequency (the pitch, in Hz) of the newest 42.7 ms of sound, and how sure
 * it is. No task of its own: the Autotune effect (audio_effects.c) calls
 * PitchDetector_ProcessBlock once per block, inside FxRenderTask. Input:
 * 48 kHz mono 16-bit PCM (plain signed sample values).
 *
 * The idea (normalised autocorrelation): a voiced sound, such as a sung
 * vowel, repeats the same wave shape once every period T. Compare the sound
 * with a copy of itself shifted by a lag of L samples: when L = T the two
 * line up and the match is close to 1. Try every lag in the voice range,
 * keep the one that matches best, and the pitch is 1 / T.
 *
 * Main steps:
 *   1. PitchDetector_ProcessBlock: decimation (lowering the sample rate).
 *      Every 4 input samples are averaged into one (48 kHz -> 12 kHz) and
 *      the newest 512 of them are kept in a circular buffer: the analysis
 *      window, 42.7 ms.
 *   2. pd_estimate, as soon as the window is first full, then every 256 new
 *      samples (21.3 ms):
 *      a. remove the window's average; a window quieter than PD_SILENCE_RMS
 *         is silence: no pitch
 *      b. for every lag from 12 to 150 (1000 Hz down to 80 Hz), the
 *         normalised correlation of the window with itself shifted by the
 *         lag: +1 = the same shape, 0 = unrelated (noise), -1 = opposite
 *      c. the best value under PD_MIN_CONFIDENCE (0.55): no clear pitch
 *         (noise, a breath, an "s")
 *      d. take the FIRST peak that reaches 85 % of the best one, not simply
 *         the highest (this avoids octave errors, see below)
 *      e. fit a parabola through that peak and its two neighbours to find
 *         the lag between whole samples; pitch = 12000 / lag
 *   3. Between two analyses every call returns the same, latest answer.
 *
 * Why decimate: the pitches searched (80-1000 Hz) still show clearly at
 * 12 kHz (12 kHz samples can carry up to 6 kHz), and with 4 times fewer
 * samples AND 4 times fewer lags the correlation costs about 16 times less
 * than at 48 kHz. Averaging 4 samples is also a simple low-pass filter: it
 * weakens the high frequencies that 12 kHz samples cannot carry.
 *
 * Tests: Tests/AudioEffects/test_pitch_detector.c.
 */
#include "pitch_detector.h"

#include <math.h>
#include <string.h>

/*
 * The numbers (lag = shift in samples at 12 kHz; pitch = 12000 / lag):
 *   PD_DECIMATED_RATE_HZ   48 kHz / PITCH_DETECTOR_DECIMATION, written out
 *   PD_MIN_LAG, PD_MAX_LAG lags 12..150: pitches from 1000 Hz down to 80 Hz,
 *                          roughly the pitch range of human voices,
 *                          speaking or singing
 *   PD_MIN_CONFIDENCE      below this best correlation the sound does not
 *                          repeat clearly enough to trust a pitch (Autotune
 *                          asks for 0.70 on top of this, in audio_effects.c)
 *   PD_SILENCE_RMS         RMS (root mean square: the average size of the
 *                          wave, 1.0 = full scale) under which the window
 *                          counts as silence: about 46 dB below full scale,
 *                          an RMS of about 164 out of 32768
 *   PD_EPSILON             keeps the division away from 0 when part of the
 *                          window is all zeros
 */
#define PD_DECIMATED_RATE_HZ      12000.0f
#define PD_MIN_LAG                12U   /* 1000 Hz at 12 kHz */
#define PD_MAX_LAG                150U  /* 80 Hz at 12 kHz */
#define PD_MIN_CONFIDENCE         0.55f
#define PD_SILENCE_RMS            0.005f
#define PD_EPSILON                1.0e-12f

/**
 * @brief Read one sample from the circular analysis buffer in chronological order.
 * @param detector Persistent detector state.
 * @param chronological_index Index from oldest (0) to newest analysis sample.
 * @return Requested normalised floating-point sample.
 */
static float pd_get_sample(const PitchDetector *detector, uint16_t chronological_index)
{
    const uint16_t index = (uint16_t)((detector->write_index + chronological_index)
                                      % PITCH_DETECTOR_BUFFER_SIZE);
    return detector->buffer[index];
}

/**
 * @brief Estimate fundamental frequency using normalised autocorrelation.
 * @param detector Detector containing a full decimated analysis window.
 */
static void pd_estimate(PitchDetector *detector)
{
    float mean = 0.0f;
    float energy = 0.0f;
    float correlations[PD_MAX_LAG + 1U] = {0.0f};
    uint16_t best_lag = PD_MIN_LAG;
    float best_correlation = -1.0f;

    /* a. The window's average is taken off every sample (a constant offset
       would make every lag look alike), then its level decides silence. */
    for (uint16_t i = 0U; i < PITCH_DETECTOR_BUFFER_SIZE; ++i)
    {
        mean += pd_get_sample(detector, i);
    }
    mean /= (float)PITCH_DETECTOR_BUFFER_SIZE;

    for (uint16_t i = 0U; i < PITCH_DETECTOR_BUFFER_SIZE; ++i)
    {
        const float x = pd_get_sample(detector, i) - mean;
        energy += x * x;
    }

    const float rms = sqrtf(energy / (float)PITCH_DETECTOR_BUFFER_SIZE);
    if (rms < PD_SILENCE_RMS)
    {
        detector->pitch_valid = false;
        detector->last_pitch_hz = 0.0f;
        detector->last_confidence = 0.0f;
        return;
    }

    /*
     * b. Normalised correlation for each lag, over the part where the window
     *    and its shifted copy overlap (512 - lag samples; a = the sample,
     *    b = the sample lag later, both with the average taken off):
     *        correlation = sum(a * b) / sqrt(sum(a * a) * sum(b * b))
     *    Dividing by the two energies keeps it between -1 and +1 however
     *    loud the voice is. The best lag so far is kept as we go.
     */
    for (uint16_t lag = PD_MIN_LAG; lag <= PD_MAX_LAG; ++lag)
    {
        float numerator = 0.0f;
        float energy_a = 0.0f;
        float energy_b = 0.0f;
        const uint16_t count = (uint16_t)(PITCH_DETECTOR_BUFFER_SIZE - lag);

        for (uint16_t i = 0U; i < count; ++i)
        {
            const float a = pd_get_sample(detector, i) - mean;
            const float b = pd_get_sample(detector, (uint16_t)(i + lag)) - mean;
            numerator += a * b;
            energy_a += a * a;
            energy_b += b * b;
        }

        const float denominator = sqrtf(energy_a * energy_b) + PD_EPSILON;
        const float correlation = numerator / denominator;
        correlations[lag] = correlation;

        if (correlation > best_correlation)
        {
            best_correlation = correlation;
            best_lag = lag;
        }
    }

    /* c. Not even the best lag matches well: noise or an unvoiced sound. */
    if (best_correlation < PD_MIN_CONFIDENCE)
    {
        detector->pitch_valid = false;
        detector->last_pitch_hz = 0.0f;
        detector->last_confidence = best_correlation;
        return;
    }

    /* d. Prefer the first strong local positive peak. This reduces the tendency
       to lock onto a later multiple of the fundamental period.
       Why: a sound that repeats every T samples also repeats every 2T and
       3T, so the correlation has peaks there too, and one of them can come
       out a little higher. Taking the highest would then report half the
       pitch (an octave error). "Strong" = at least 85 % of the best value
       and never under PD_MIN_CONFIDENCE; lag 12 has no left neighbour, so it
       only has to be at least as high as lag 13. No such peak: the best lag
       is kept. */
    const float peak_threshold = fmaxf(PD_MIN_CONFIDENCE, 0.85f * best_correlation);
    uint16_t chosen_lag = best_lag;

    if ((correlations[PD_MIN_LAG] >= peak_threshold) &&
        (correlations[PD_MIN_LAG] >= correlations[PD_MIN_LAG + 1U]))
    {
        chosen_lag = PD_MIN_LAG;
    }
    else
    {
        for (uint16_t lag = PD_MIN_LAG + 1U; lag < PD_MAX_LAG; ++lag)
        {
            if ((correlations[lag] >= peak_threshold) &&
                (correlations[lag] >= correlations[lag - 1U]) &&
                (correlations[lag] > correlations[lag + 1U]))
            {
                chosen_lag = lag;
                break;
            }
        }
    }

    /*
     * e. Parabolic interpolation. Whole lags are coarse for high voices:
     *    lag 12 is 1000 Hz but lag 13 is 923 Hz, more than a semitone lower.
     *    A parabola through the correlation at lag-1, lag and lag+1 (y1, y2,
     *    y3) has its top at lag + delta, delta = 0.5 (y1 - y3) /
     *    (y1 - 2 y2 + y3). The middle point is a peak, so the top is always
     *    within half a lag of it; the clamp to +-0.5 is only a safety net.
     *    Skipped at the two ends of the lag range (no neighbour there) and
     *    when the three points lie on a straight line.
     */
    float refined_lag = (float)chosen_lag;
    if ((chosen_lag > PD_MIN_LAG) && (chosen_lag < PD_MAX_LAG))
    {
        const float y1 = correlations[chosen_lag - 1U];
        const float y2 = correlations[chosen_lag];
        const float y3 = correlations[chosen_lag + 1U];
        const float denominator = y1 - (2.0f * y2) + y3;

        if (fabsf(denominator) > 1.0e-6f)
        {
            float delta = 0.5f * (y1 - y3) / denominator;
            if (delta > 0.5f) delta = 0.5f;
            if (delta < -0.5f) delta = -0.5f;
            refined_lag += delta;
        }
    }

    /* Pitch in Hz = 12000 / lag; the confidence is the chosen lag's correlation. */
    detector->last_pitch_hz = PD_DECIMATED_RATE_HZ / refined_lag;
    detector->last_confidence = correlations[chosen_lag];
    detector->pitch_valid = detector->last_confidence >= PD_MIN_CONFIDENCE;
}

/**
 * @brief Initialise a detector to empty state.
 * @param detector Detector state; NULL is safely ignored.
 */
void PitchDetector_Init(PitchDetector *detector)
{
    PitchDetector_Reset(detector);
}

/**
 * @brief Clear buffered samples and the previous pitch estimate.
 * @param detector Detector state; NULL is safely ignored.
 */
void PitchDetector_Reset(PitchDetector *detector)
{
    if (detector == NULL)
    {
        return;
    }

    memset(detector, 0, sizeof(*detector));
}

/**
 * @brief Accumulate PCM samples and return the latest pitch estimate.
 * @param detector Persistent detector state.
 * @param input Signed 16-bit mono PCM samples.
 * @param sample_count Number of samples; must be greater than zero.
 * @param pitch_hz Optional pitch output.
 * @param confidence Optional correlation-confidence output.
 * @return true when a valid pitch estimate is available.
 */
bool PitchDetector_ProcessBlock(PitchDetector *detector,
                                const int16_t *input,
                                size_t sample_count,
                                float *pitch_hz,
                                float *confidence)
{
    if ((detector == NULL) || (input == NULL) || (sample_count == 0U))
    {
        if (pitch_hz != NULL) *pitch_hz = 0.0f;
        if (confidence != NULL) *confidence = 0.0f;
        return false;
    }

    for (size_t i = 0U; i < sample_count; ++i)
    {
        /* Decimation: scale to -1..1 and average each group of 4 samples
           into one 12 kHz sample in the circular window. */
        detector->decimation_accumulator += (float)input[i] / 32768.0f;
        detector->decimation_count++;

        if (detector->decimation_count == PITCH_DETECTOR_DECIMATION)
        {
            const float decimated = detector->decimation_accumulator
                                  / (float)PITCH_DETECTOR_DECIMATION;

            detector->buffer[detector->write_index] = decimated;
            detector->write_index++;
            if (detector->write_index >= PITCH_DETECTOR_BUFFER_SIZE)
            {
                detector->write_index = 0U;
            }

            detector->decimation_accumulator = 0.0f;
            detector->decimation_count = 0U;

            if (detector->total_decimated_samples < PITCH_DETECTOR_BUFFER_SIZE)
            {
                detector->total_decimated_samples++;
            }

            /* Once the window is full: analyse at once the first time, then
               every PITCH_DETECTOR_UPDATE_DECIMATED (256) new samples. */
            if (detector->total_decimated_samples >= PITCH_DETECTOR_BUFFER_SIZE)
            {
                detector->decimated_since_analysis++;

                if ((!detector->has_analysed) ||
                    (detector->decimated_since_analysis >= PITCH_DETECTOR_UPDATE_DECIMATED))
                {
                    pd_estimate(detector);
                    detector->has_analysed = true;
                    detector->decimated_since_analysis = 0U;
                }
            }
        }
    }

    if (pitch_hz != NULL)
    {
        *pitch_hz = detector->pitch_valid ? detector->last_pitch_hz : 0.0f;
    }
    if (confidence != NULL)
    {
        *confidence = detector->last_confidence;
    }

    return detector->pitch_valid;
}

/**
 * @brief Input samples since the newest estimate, or -1 if none yet.
 * @param detector Detector state.
 * @return Samples since the estimate, or -1.
 *
 * The estimate is made on the last sample of a group of 4, and both
 * counters restart there, so: 4 x (12 kHz samples since) + (input samples
 * in the group now being filled).
 */
int32_t PitchDetector_SamplesSinceEstimate(const PitchDetector *detector)
{
    if ((detector == NULL) || (!detector->has_analysed))
    {
        return -1;
    }
    return (int32_t)(PITCH_DETECTOR_DECIMATION * detector->decimated_since_analysis)
         + (int32_t)detector->decimation_count;
}
